insert into public.places (slug, name, category, lat, lng, description, tip, radius_m, status) values
  ('vysehrad-hradby', 'Hradby Vyšehradu', 'view', 50.0644, 14.4178, 'Procházka po hradbách s výhledem na Vltavu, Podolí a Hrad. Nejhezčí těsně před západem slunce.', 'Obejdi hradby celé dokola, nejlepší výhled je na jihozápadním cípu.', 150, 'approved'),
  ('riegrovy-sady', 'Riegrovy sady – vyhlídka', 'view', 50.0803, 14.4417, 'Travnatý svah, ze kterého je vidět Hrad jako na dlani. Místní sem chodí na západ slunce.', 'Vezmi si deku a něco k pití.', 150, 'approved'),
  ('letna-metronom', 'Metronom na Letné', 'view', 50.09474, 14.41594, 'Obří metronom na místě bývalého Stalinova pomníku a výhled na pražské mosty.', 'V létě tu pod metronomem bývá bar a skejťáci.', 70, 'approved'),
  ('vitkov', 'Vrch Vítkov', 'view', 50.0884, 14.4497, 'Obří jezdecká socha Jana Žižky a výhled na Žižkov i Karlín z jednoho místa.', 'Zpátky to vezmi dolů do Karlína na kávu.', 150, 'approved'),
  ('divoka-sarka', 'Divoká Šárka', 'nature', 50.09943, 14.32014, 'Skalnaté údolí s potokem, které vůbec nevypadá jako Praha.', 'Vylez na skálu Dívčí skok, výhled stojí za to.', 150, 'approved'),
  ('prokopske-udoli', 'Prokopské údolí – jezírko', 'nature', 50.04181, 14.38618, 'Malé jezírko v bývalém lomu schované v zeleném údolí.', 'Pokračuj údolím dál, je tu klid i o víkendu.', 150, 'approved'),
  ('grebovka', 'Grébovka', 'chill', 50.06924, 14.44495, 'Park s vinicí, altánem a umělou jeskyní uprostřed Vinohrad.', 'Ve viničním altánu si dej sklenku s výhledem na Nusle.', 150, 'approved'),
  ('stromovka', 'Stromovka', 'nature', 50.10648, 14.4127, 'Největší pražský park s rybníky, starými stromy a spoustou místa.', 'Projdi až k Vltavě a přívozem nebo lávkou pokračuj do Troje.', 250, 'approved'),
  ('ladronka', 'Ladronka', 'chill', 50.07854, 14.35628, 'Dlouhý rovný park na Břevnově s usedlostí, kde se dá posedět.', 'Ideální na brusle nebo kolo.', 150, 'approved'),
  ('letohradek-hvezda', 'Letohrádek Hvězda', 'culture', 50.08339, 14.32621, 'Renesanční letohrádek s půdorysem šesticípé hvězdy uprostřed obory.', 'Obora je skvělá na dlouhou procházku lesem.', 70, 'approved'),
  ('petrin-rozhledna', 'Petřínská rozhledna', 'view', 50.08352, 14.39509, 'Malá sestra Eiffelovky na kopci nad Malou Stranou.', 'Dolů sejdi sady směrem na Újezd.', 70, 'approved'),
  ('werichova-vila', 'Werichova vila na Kampě', 'culture', 50.0854, 14.40802, 'Vila u Čertovky, kde žil Jan Werich, dnes s výstavami a kavárnou.', 'Hned vedle je park Kampa a mlýnské kolo.', 70, 'approved'),
  ('naplavka', 'Náplavka', 'chill', 50.0707, 14.4142, 'Nábřeží u Vltavy plné lidí, labutí a barů v kobkách.', 'V sobotu dopoledne tu bývají farmářské trhy.', 150, 'approved'),
  ('zizkovska-vez', 'Žižkovská věž', 'view', 50.08102, 14.45106, 'Televizní vysílač s lezoucími miminky od Davida Černého.', 'Pod věží je zahrádka a minigolf.', 70, 'approved'),
  ('parukarka', 'Parukářka', 'view', 50.08519, 14.46068, 'Žižkovský kopec s hospodou a jedním z nejlepších západů slunce ve městě.', 'Pivo z kelímku na trávě k tomu patří.', 150, 'approved'),
  ('vrtbovska-zahrada', 'Vrtbovská zahrada', 'hidden', 50.08649, 14.40248, 'Barokní terasová zahrada schovaná za nenápadným průjezdem na Malé Straně.', 'Otevřeno jen v sezóně, vstup je placený.', 70, 'approved'),
  ('vojanovy-sady', 'Vojanovy sady', 'hidden', 50.08876, 14.40846, 'Tichá zahrada za vysokou zdí, kde se procházejí pávi.', 'Vchod je z ulice U Lužického semináře.', 70, 'approved'),
  ('frantiskanska-zahrada', 'Františkánská zahrada', 'hidden', 50.08215, 14.42393, 'Klidná zahrada pár kroků od Václavského náměstí, kterou spousta lidí mine.', 'Dá se sem dostat pasáží Světozor, vezmi si tam zmrzlinu.', 70, 'approved'),
  ('novy-svet', 'Nový Svět', 'hidden', 50.09092, 14.39144, 'Ulička malých domků za Hradem, kde se zastavil čas a nejsou tu davy.', 'Projdi ji celou a pokračuj k Loretě.', 100, 'approved'),
  ('trojsky-zamek', 'Trojský zámek', 'culture', 50.1164, 14.41302, 'Barokní zámek se zahradami a schodištěm plným soch.', 'Kousek nad ním jsou vinice sv. Kláry s výhledem.', 70, 'approved'),
  ('botanicka-troja', 'Botanická zahrada v Troji', 'nature', 50.12062, 14.41623, 'Zahrady ve svahu nad Vltavou a tropický skleník Fata Morgana.', 'Japonská zahrada je nejhezčí na jaře a na podzim.', 150, 'approved'),
  ('zricenina-baba', 'Zřícenina Baba', 'view', 50.1188, 14.39068, 'Malá zřícenina na skále vysoko nad Vltavou s výhledem na Troju.', 'Cestou si prohlédni funkcionalistické vily osady Baba.', 70, 'approved'),
  ('divci-hrady', 'Dívčí hrady', 'view', 50.05361, 14.3992, 'Planina nad Smíchovem s širokým výhledem na celé město.', 'V ohradě se tu pasou koně Převalského.', 250, 'approved'),
  ('strelecky-ostrov', 'Střelecký ostrov', 'chill', 50.08128, 14.41003, 'Ostrov pod mostem Legií, kde sedíš přímo u hladiny s výhledem na Národní divadlo.', 'Dojdi až na severní špičku ostrova.', 150, 'approved'),
  ('kasarna-karlin', 'Kasárna Karlín', 'culture', 50.09029, 14.44445, 'Bývalá kasárna proměněná v dvůr s barem, kinem a pískovištěm.', 'Program se mění, večer tu často něco hraje.', 70, 'approved'),
  ('meetfactory', 'MeetFactory', 'culture', 50.05325, 14.40818, 'Umělecká továrna mezi kolejemi a magistrálou s červenými auty na fasádě.', 'Galerie bývají přístupné zdarma.', 70, 'approved'),
  ('vystaviste', 'Výstaviště Holešovice', 'culture', 50.10671, 14.4303, 'Secesní Průmyslový palác a areál, kde se pořád něco děje.', 'Odsud je to kousek do Stromovky.', 150, 'approved'),
  ('kinskeho-zahrada', 'Kinského zahrada', 'nature', 50.07847, 14.39458, 'Park ve svahu Petřína s jezírky a dřevěným kostelíkem.', 'Najdi kostelík svatého Michala přivezený z Podkarpatské Rusi.', 150, 'approved'),
  ('hostivarska-prehrada', 'Hostivařská přehrada', 'nature', 50.04317, 14.53058, 'Největší vodní plocha v Praze s lesoparkem okolo.', 'Okruh kolem přehrady je příjemná procházka na hodinu a půl.', 150, 'approved'),
  ('kunraticky-les', 'Kunratický les', 'nature', 50.0274, 14.47392, 'Rozlehlý les na jihu Prahy s potokem a zříceninou Nového hradu.', 'Hledej zbytky hradu, kde zemřel Václav IV.', 250, 'approved'),
  ('hanavsky-pavilon', 'Hanavský pavilon', 'view', 50.09366, 14.41261, 'Litinový pavilon z Jubilejní výstavy 1891 na hraně Letné. Mosty přes Vltavu odsud vypadají jako seřazené za sebou.', 'Nejhezčí je to tu ráno, kdy je na vyhlídce prázdno.', 70, 'approved'),
  ('dobeska', 'Vyhlídka Dobeška', 'view', 50.04311, 14.41486, 'Malý plácek nad Braníkem s výhledem na Vltavu, Barrandov a jižní okraj Prahy. Chodí sem hlavně místní.', 'Vezmi si něco s sebou, na vyhlídce nic nekoupíš.', 100, 'approved'),
  ('bastion', 'Bastion u Božích muk', 'view', 50.06799, 14.42729, 'Zrekonstruovaná část novoměstských hradeb nad Albertovem s výhledem na Vyšehrad a Nuselský most.', 'Projdi se podél hradeb dál směrem ke Karlovu.', 70, 'approved'),
  ('sacre-coeur', 'Park Sacré Coeur', 'view', 50.07383, 14.3995, 'Louka nad Smíchovem, kam si místní chodí lehnout do trávy. Dolů je vidět Anděl, nahoře je klid.', 'Dá se sem dojít po schodech přímo od nákupního centra na Andělu.', 150, 'approved'),
  ('santoska', 'Santoška', 'view', 50.06454, 14.39849, 'Park ve svahu nad Smíchovem se starou usedlostí a výhledem přes údolí na Vyšehrad.', 'Pokračuj nahoru na Paví vrch, je odtamtud ještě lepší rozhled.', 150, 'approved'),
  ('devin', 'Děvín', 'view', 50.04708, 14.40132, 'Travnatý kopec mezi Smíchovem a Prokopským údolím. Rozhled do všech stran a skoro žádní lidé.', 'Spoj to s procházkou do Prokopského údolí pod kopcem.', 150, 'approved'),
  ('vidoule', 'Vidoule', 'view', 50.06059, 14.359, 'Stolová hora nad Jinonicemi. Nahoře je rovná pláň, ze které je vidět Hrad i letadla mířící na Ruzyni.', 'Okraje plošiny jsou strmé, drž se vyšlapaných cest.', 250, 'approved'),
  ('butovicke-hradiste', 'Butovické hradiště', 'view', 50.04112, 14.35781, 'Ostroh nad Prokopským údolím, kde stávalo slovanské hradiště. Dnes louka s výhledem do údolí.', 'Sejdi dolů k Hlubočepskému jezírku.', 150, 'approved'),
  ('tresnovka', 'Třešňovka v Hrdlořezích', 'view', 50.09715, 14.50591, 'Starý třešňový sad na kopci s výhledem na Žižkov a Vysočany. Na jaře kvete, v červnu se dá trhat.', 'Vem si deku, lavičky tu skoro nejsou.', 150, 'approved'),
  ('zlichov-kostelik', 'Kostelík na Zlíchově', 'view', 50.04735, 14.40884, 'Malý kostel na skále přímo nad Vltavou a rušnou silnicí. Zespodu vypadá nedostupně, nahoře je ticho.', 'Nahoru vede cesta z ulice Na Zlíchově.', 70, 'approved'),
  ('strahov-vyhlidka', 'Vyhlídka u Strahovského kláštera', 'view', 50.08626, 14.38907, 'Zahrady pod Strahovským klášterem nabízejí jeden z nejširších výhledů na Malou Stranu a Staré Město.', 'Sejdi odsud pěšinou přes Petřín dolů na Újezd.', 150, 'approved'),
  ('zemedelske-muzeum', 'Střecha Zemědělského muzea', 'view', 50.09707, 14.42324, 'Na střeše muzea na Letné je zahrada s výhledem na město. Většina lidí o ní neví.', 'Na střechu se chodí přes muzeum, počítej se vstupným.', 70, 'approved'),
  ('libensky-zamek', 'Libeňský zámek a Thomayerovy sady', 'chill', 50.10871, 14.46641, 'Rokokový zámeček a pod ním klidný park s potokem Rokytkou. Libeň, jak ji znal Hrabal.', 'Projdi parkem až k soutoku Rokytky s Vltavou.', 150, 'approved'),
  ('cimicky-haj', 'Čimický háj', 'nature', 50.12994, 14.44033, 'Lesopark mezi sídlišti na severu Prahy. Stačí pár kroků a je z toho obyčejný les.', 'Uprostřed háje je rybníček a louka na piknik.', 250, 'approved'),
  ('dablicky-haj', 'Ďáblický háj', 'nature', 50.1358, 14.46432, 'Les na kopci Ládví s hvězdárnou na okraji. Z vrcholu je vidět daleko do Polabí.', 'Ďáblická hvězdárna pořádá večerní pozorování.', 250, 'approved'),
  ('modranska-rokle', 'Modřanská rokle', 'nature', 50.00269, 14.43769, 'Zalesněné údolí Libušského potoka. Cesta vede kolem tůní a mokřadů a z města tu není slyšet nic.', 'Rokle se dá projít celá, z Modřan až do Libuše.', 250, 'approved'),
  ('milicovsky-les', 'Milíčovský les a rybníky', 'nature', 50.02346, 14.54235, 'Les a soustava rybníků hned za Jižním Městem. Chodí se sem dívat na ptáky a na staré duby.', 'Okruh kolem rybníků zabere asi hodinu.', 250, 'approved'),
  ('klanovicky-les', 'Klánovický les', 'nature', 50.07971, 14.68843, 'Největší les v Praze. Rovné dlouhé cesty, ticho a na podzim houbaři.', 'Do lesa se dostaneš vlakem, zastávka Praha-Klánovice je přímo u něj.', 250, 'approved'),
  ('pocernicky-rybnik', 'Počernický rybník', 'nature', 50.08818, 14.58181, 'Největší pražský rybník s rákosinami a starým mlýnem. Okolo vede pěšina.', 'Na hrázi je místo, odkud je dobře vidět na vodní ptáky.', 150, 'approved'),
  ('dalejske-udoli', 'Dalejské údolí', 'nature', 50.03294, 14.3525, 'Údolí Dalejského potoka s vápencovými skalami a starými lomy. Navazuje na Prokopské údolí, ale je tišší.', 'Cestou mineš starý mlýn a železniční viadukty.', 250, 'approved'),
  ('chuchelsky-haj', 'Chuchelský háj', 'nature', 50.01993, 14.38179, 'Les nad Malou Chuchlí s kostelíkem a malým zookoutkem se zvířaty z českých lesů.', 'Zookoutek je zdarma a baví i dospělé.', 250, 'approved'),
  ('cisarsky-ostrov', 'Císařský ostrov', 'nature', 50.11628, 14.39653, 'Dlouhý ostrov mezi Stromovkou a Trojou. Louky, koně a cesta podél vody.', 'Z ostrova vede lávka do Troje k zámku a zoo.', 250, 'approved'),
  ('stvanice', 'Ostrov Štvanice', 'chill', 50.09535, 14.44114, 'Ostrov uprostřed Vltavy mezi Karlínem a Holešovicemi. Na špičce se sedí přímo u vody.', 'Na ostrov vede z Karlína i z Holešovic lávka pro pěší.', 150, 'approved'),
  ('rohansky-ostrov', 'Rohanský ostrov', 'nature', 50.0997, 14.45995, 'Zarostlý pruh země mezi Karlínem a řekou s cyklostezkou. Kus divočiny pár minut od kanceláří.', 'Po stezce dojdeš podél vody až do Libně.', 250, 'approved'),
  ('ruzovy-sad', 'Růžový sad na Petříně', 'nature', 50.08155, 14.39668, 'Zahrada s tisíci růží hned vedle rozhledny a hvězdárny. V červnu voní celý kopec.', 'Kvete od června do září, mimo sezónu je tu aspoň klid.', 150, 'approved'),
  ('klamovka', 'Klamovka', 'chill', 50.07152, 14.37925, 'Starý park v Košířích s altánem, rokokovým pavilonem a hospodou se zahrádkou.', 'Hledej v parku novogotický chrámek ve svahu.', 150, 'approved'),
  ('cibulka', 'Cibulka', 'hidden', 50.06683, 14.35692, 'Romantický lesopark kolem staré usedlosti. V lese je schovaná malá rozhledna a čínský pavilon.', 'Rozhledna je volně přístupná, hledej ji nad usedlostí.', 150, 'approved'),
  ('jezerka', 'Park Jezerka', 'chill', 50.05738, 14.44397, 'Malý park v Nuslích s jezírkem a divadlem v zámečku. Znají ho hlavně lidé z okolí.', 'Je to dobrá zastávka cestou z Vyšehradu na Pankrác.', 150, 'approved'),
  ('folimanka', 'Folimanka', 'chill', 50.06792, 14.43006, 'Park v údolí Botiče přímo pod Nuselským mostem. Most odsud vypadá obrovský.', 'V parku je vchod do protiatomového krytu, občas bývá otevřený.', 150, 'approved'),
  ('zidovske-pece', 'Židovské pece', 'chill', 50.089, 14.47897, 'Travnatý park na kopci na konci Žižkova. Méně známý soused Parukářky.', 'V létě tu bývá otevřená zahrádka.', 150, 'approved'),
  ('malesicky-park', 'Malešický park', 'chill', 50.08456, 14.49845, 'Opravený park s vodními prvky, loukami a místy na sezení. Mimo centrum, a proto poloprázdný.', 'Děti tu mají velké hřiště s vodou.', 150, 'approved'),
  ('hamersky-rybnik', 'Hamerský rybník', 'nature', 50.05282, 14.48748, 'Rybník na Botiči ve staré části Záběhlic s kostelíkem na břehu.', 'Podél Botiče vede odsud stezka do Hostivaře.', 150, 'approved'),
  ('meandry-botice', 'Meandry Botiče', 'nature', 50.04799, 14.53328, 'Úsek, kde Botič teče přirozeným korytem mezi stromy. Vypadá to jako za městem.', 'Stezka pokračuje až k Hostivařské přehradě.', 150, 'approved'),
  ('park-pratelstvi', 'Park Přátelství', 'chill', 50.12063, 14.49677, 'Dlouhý park uprostřed sídliště Prosek s potůčkem a jezírky. Ukázka toho, jak může sídliště vypadat.', 'Nejhezčí je projít ho celý od metra Prosek ke Střížkovu.', 150, 'approved'),
  ('podvini', 'Park Podviní', 'nature', 50.1106, 14.49263, 'Park podél Rokytky ve Vysočanech s loukami a hřišti. Vede tudy cyklostezka.', 'Podél Rokytky se dá dojít až do Hrdlořez.', 150, 'approved'),
  ('zlute-lazne', 'Žluté lázně', 'chill', 50.0489, 14.41412, 'Říční plovárna v Podolí s pláží, hřišti a bary. V létě tu místní tráví celé dny.', 'Mimo léto bývá areál přístupný zdarma na procházku.', 150, 'approved'),
  ('branicke-skaly', 'Branické skály', 'nature', 50.04246, 14.41374, 'Vápencová stěna bývalého lomu nad Braníkem. Nahoře je stepní louka s výhledem na řeku.', 'Nahoru se jde od ulice Nad Lomem.', 150, 'approved'),
  ('obora-satalice', 'Satalická obora', 'nature', 50.12847, 14.57628, 'Malá bažantnice se starými duby na severovýchodě Prahy. Aleje a žádné davy.', 'Navazuje na ni Vinořský park, dá se to spojit v jednu procházku.', 250, 'approved'),
  ('vinorsky-park', 'Vinořský park', 'nature', 50.14055, 14.58523, 'Zarostlý park s pískovcovými skalkami a rybníky u zámku ve Vinoři.', 'Hledej skalní útvary podél potoka.', 250, 'approved'),
  ('ctenice', 'Zámek Ctěnice', 'culture', 50.14939, 14.56399, 'Zámek na samém okraji Prahy s parkem, výstavami a jízdárnou.', 'Park je volně přístupný a dá se odsud dojít do Vinoře.', 70, 'approved'),
  ('kunraticky-zamek', 'Zámecký park Kunratice', 'chill', 50.0122, 14.48235, 'Klidný park kolem zámku ve staré části Kunratic.', 'Odsud je to kousek do Kunratického lesa.', 150, 'approved'),
  ('nejuzsi-ulicka', 'Nejužší ulička v Praze', 'hidden', 50.08786, 14.40951, 'Průchod na Malé Straně tak úzký, že má vlastní semafor. Dva lidé se v něm nevyhnou.', 'Je to jen pár schodů, ale zmáčkni si semafor.', 70, 'approved'),
  ('velkoprevorsky-mlyn', 'Velkopřevorský mlýn', 'hidden', 50.08624, 14.40746, 'Mlýnské kolo na Čertovce a u něj dřevěný vodník. Jedno z nejklidnějších míst na Kampě.', 'Nejlíp je vidět z můstku u Lennonovy zdi.', 70, 'approved'),
  ('ztracenka', 'Zahrada Ztracenka', 'hidden', 50.06844, 14.4267, 'Terasová zahrada ve svahu mezi Karlovem a Albertovem. Dlouho byla zavřená a málokdo ji zná.', 'Z horní terasy je vidět Vyšehrad.', 70, 'approved'),
  ('jeleni-prikop', 'Jelení příkop', 'hidden', 50.09221, 14.40279, 'Zalesněná rokle přímo pod Pražským hradem. Kdysi se tu chovala zvěř, dnes je to tichá stezka.', 'Bývá otevřený jen v sezóně a po dešti se zavírá.', 150, 'approved'),
  ('svatovaclavska-vinice', 'Svatováclavská vinice', 'view', 50.09224, 14.40737, 'Vinice pod Pražským hradem s výhledem na Malou Stranu a na řeku.', 'Projdi vinicí dolů ke Klárovu.', 150, 'approved'),
  ('anezsky-klaster', 'Zahrady Anežského kláštera', 'hidden', 50.09226, 14.42399, 'Volně přístupné zahrady kolem gotického kláštera na okraji Starého Města. Sochy a ticho.', 'Do zahrad se vstupuje zdarma z ulice Anežská.', 70, 'approved'),
  ('ungelt', 'Ungelt', 'hidden', 50.08793, 14.42395, 'Uzavřený dvůr za Týnským chrámem, kde středověcí kupci platili clo. Pár kroků od náměstí a o poznání klidnější.', 'Projdi ho skrz do Malé Štupartské.', 100, 'approved'),
  ('lucerna', 'Pasáž Lucerna', 'hidden', 50.08113, 14.42604, 'Pasáž z počátku 20. století s kinem a kavárnou. U stropu visí svatý Václav na koni vzhůru nohama.', 'Kavárna v patře má výhled přímo na sochu.', 70, 'approved'),
  ('frantiskani-svetozor', 'Pasáž Světozor', 'hidden', 50.08185, 14.42499, 'Průchod z Vodičkovy s velkou skleněnou vitráží a vyhlášenou zmrzlinou.', 'Pasáží se projde do Františkánské zahrady.', 70, 'approved'),
  ('kubisticka-lampa', 'Kubistická lampa', 'hidden', 50.08331, 14.42369, 'Pouliční lampa z roku 1913 v kubistickém stylu. Stojí v koutě za kostelem Panny Marie Sněžné a snadno ji mineš.', 'Je to jediná kubistická pouliční lampa na světě.', 70, 'approved'),
  ('botanicka-na-slupi', 'Botanická zahrada Na Slupi', 'nature', 50.07133, 14.42202, 'Univerzitní zahrada uprostřed Nového Města. Venkovní část je volně přístupná.', 'Skleníky jsou za vstupné a stojí za to hlavně v zimě.', 150, 'approved'),
